```python
import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_MIN_DT = datetime.min
_EXT_MARKER = re.compile(r"x|ext|#", re.IGNORECASE)
_ZIP_PLUS4 = re.compile(r"([0-9]{4,5})-[0-9]{4}")
_TAG_SPLIT = re.compile(r"[;,]")


def _normalize_email(raw):
    s = (raw or "").strip()
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    local, sep, domain = s.partition("@")
    if sep and domain in _GMAIL_DOMAINS:
        local = local.replace(".", "").split("+", 1)[0]
        domain = "gmail.com"
    return local + sep + domain


def _valid_email(e):
    if e.count("@") != 1:
        return False
    local, domain = e.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw or ""
    m = _EXT_MARKER.search(s)
    if m:
        s = s[:m.start()]
    digits = re.sub(r"[^0-9]", "", s)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _valid_phone(d):
    return len(d) == 10 and d[0] not in "01"


def _normalize_zip(raw):
    z = (raw or "").strip()
    m = _ZIP_PLUS4.fullmatch(z)
    if m:
        z = m.group(1)
    if re.fullmatch(r"[0-9]{4}", z):
        z = "0" + z
    if re.fullmatch(r"[0-9]{5}", z):
        return z
    return ""


def _normalize_name(raw):
    s = (raw or "").strip()
    if s and (s.isupper() or s.islower()):
        s = s.title()
    return s


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return _MIN_DT


def _opted_out(raw):
    return (raw or "").strip().lower() in {"y", "yes", "true", "1"}


def _normalize_tags(raw):
    tags = []
    for t in _TAG_SPLIT.split(raw or ""):
        t = t.strip().lower()
        if t:
            tags.append(t)
    return tags


def _pick(members, field):
    """Pick the value of `field` from the group's rows where it is non-empty.

    Preference: manual source first, then most recent `updated`, then the
    earlier input row. Each sort is stable, so the passes compose correctly.
    """
    cands = [m for m in members if m[field]]
    cands.sort(key=lambda m: m["idx"])
    cands.sort(key=lambda m: m["updated"], reverse=True)
    cands.sort(key=lambda m: not m["manual"])
    return cands[0][field] if cands else ""


def dedupe_contacts(rows):
    # Normalize every row and drop those with neither a valid email nor a valid phone.
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email"))
        phone = _normalize_phone(row.get("phone"))
        email_ok = _valid_email(email)
        phone_ok = _valid_phone(phone)
        if not email_ok and not phone_ok:
            continue
        source = (row.get("source") or "").strip().lower()
        recs.append({
            "idx": idx,
            "first_name": _normalize_name(row.get("first_name")),
            "last_name": _normalize_name(row.get("last_name")),
            "zip": _normalize_zip(row.get("zip")),
            "email": email if email_ok else "",
            "phone": phone if phone_ok else "",
            "source": source,
            "manual": source == "manual",
            "tags": _normalize_tags(row.get("tags")),
            "opted_out": _opted_out(row.get("opted_out")),
            "updated": _parse_updated(row.get("updated")),
        })

    # Union-find over record positions, so matching is transitive.
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    email_seen = {}
    phone_seen = {}
    for pos, r in enumerate(recs):
        if r["email"]:
            if r["email"] in email_seen:
                union(pos, email_seen[r["email"]])
            else:
                email_seen[r["email"]] = pos
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].lower())
            if key in phone_seen:
                union(pos, phone_seen[key])
            else:
                phone_seen[key] = pos

    # Group records. Roots are ordered by each group's earliest input row.
    groups = {}
    order = []
    for pos in range(len(recs)):
        root = find(pos)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(recs[pos])

    result = []
    for root in order:
        members = groups[root]
        tag_set = set()
        for m in members:
            tag_set.update(m["tags"])
        latest = max(m["updated"] for m in members)
        result.append({
            "first_name": _pick(members, "first_name"),
            "last_name": _pick(members, "last_name"),
            "zip": _pick(members, "zip"),
            "email": _pick(members, "email"),
            "phone": _pick(members, "phone"),
            "source": _pick(members, "source"),
            "tags": ";".join(sorted(tag_set)),
            "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })
    return result
```

Notes for the send:

- **The function doesn't filter opt-outs.** It only flags them. Before sending, keep only rows with `opted_out == "N"`. Because any opt-out in a merged group marks the whole person "Y", a person who opted out through any duplicate record is excluded.
- **Require a non-empty `email`.** Someone with only a valid phone still appears in the output, but the newsletter needs an address.
- **Check the output count.** Compare the number of people returned with the number of unique emails in the export as a sanity check on the matching.
